import pytest
from tagger.notes import add_tag


def test_tags_are_independent_between_notes():
    note1 = {"id": "note1", "content": "First note"}
    note2 = {"id": "note2", "content": "Unrelated note"}

    result = add_tag(note1, "errand", [])

    assert result == ["errand"]
    assert note1["tags"] == ["errand"]
    assert note2["tags"] == []
    assert "errand" not in note2["tags"]

"""Tests for tagger/notes.py."""

from tagger.notes import add_tag


def test_tags_do_not_bleed_between_notes():
    note1 = {"id": "note1", "content": "First note"}
    note2 = {"id": "note2", "content": "Second note"}

    add_tag(note1, "errand", [])

    # The unrelated note must not inherit the tag from note1.
    assert "errand" not in note2.get("tags", [])
    assert note2.get("tags") is not note1.get("tags")
    assert note1.get("tags") == ["errand"]


def test_explicit_tags_list_is_not_shared():
    note1 = {"id": "note1", "content": "First note"}
    note2 = {"id": "note2", "content": "Second note"}

    shared_tags = ["shared"]
    add_tag(note1, "errand", shared_tags)

    assert note1.get("tags") == ["shared", "errand"]
    assert note2.get("tags") == ["shared"]
    assert shared_tags is not note1.get("tags")
    assert shared_tags is not note2.get("tags")

