import pytest
from protein_translation import proteins

def test_translation_basic():
    assert proteins('AUGUUUUCU') == ['Methionine', 'Phenylalanine', 'Serine']

def test_stop_codon_stops_processing():
    assert proteins('AUGUUUUCUUAAAUG') == ['Methionine', 'Phenylalanine', 'Serine']

def test_empty_sequence():
    assert proteins('') == []

def test_invalid_length():
    assert proteins('AUGU') == []

def test_all_stop_codons():
    assert proteins('UAA') == []
    assert proteins('UAG') == []
    assert proteins('UGA') == []

def test_multiple_stop_codons():
    assert proteins('AUGUAAUAG') == ['Methionine']

